"""Report gains and regressions together, on the same frozen fresh cases."""
import json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd


def report(out='data/risk/20261109_v5'):
    out=Path(out);summary=json.loads((out/'summary.json').read_text());metrics=json.loads((out/'fresh_audit_metrics.json').read_text())
    data=pd.read_parquet(out/'news_risk_scores.parquet')
    rows=metrics['results'];fig,axs=plt.subplots(1,2,figsize=(12,4),constrained_layout=True)
    cohorts=['novel_all','novel_random','novel_stress'];names=['Novel total','Random','Stress']
    colors=['#8d999e','#d0a46c','#16796f']
    for j,m in enumerate(['v3','v4','v5']):
        vals=[next(r['MAE'] for r in rows if r['model']==m and r['cohort']==c) for c in cohorts]
        axs[0].bar(np.arange(3)+(j-1)*.24,vals,.24,label=m,color=colors[j])
    axs[0].set(xticks=np.arange(3),xticklabels=names,ylabel='MAE against same-session AI (0-100)');axs[0].legend()
    values=[next(r['within10_AI_agreement']*100 for r in rows if r['model']==m and r['cohort']=='novel_all') for m in ['v3','v4','v5']]
    axs[1].bar(['v3','v4','v5'],values,color=colors);axs[1].set(ylabel='Within 10 index points: AI agreement (%)',ylim=(0,100))
    figures=out/'figures';figures.mkdir(exist_ok=True)
    for suffix in ['png','svg']:fig.savefig(figures/('fresh_accuracy_comparison.'+suffix),dpi=150)
    plt.close(fig)
    fields=['news_id','source','url','title','summary','published_date','assessment_body_sha256','assessment_research_eligible','danger_score','model_danger_score','component_index','N','T','A','S','L','I','X','score_source','session_reviewed','decision_state','rationale']
    payload=json.dumps({'summary':summary,'metrics':metrics,'articles':data[fields].to_dict('records')},ensure_ascii=False,allow_nan=False).replace('<','\\u003c').replace('&','\\u0026')
    html=r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>News2Neuron · 위험성 평가 개선</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f4f7f3;color:#163135;font:15px/1.65 system-ui,sans-serif}header{background:#143338;color:white;padding:38px max(4vw,18px)}h1{font-size:36px;line-height:1.25;margin:12px 0}header p{max-width:1050px;color:#c9ddd5}main{max-width:1400px;margin:auto;padding:22px 3vw}section,.card{background:white;border:1px solid #d5dfd9;border-radius:10px;padding:20px;margin-bottom:18px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.number{font-size:29px;font-weight:700}.muted,small{color:#52686b}h2{font-size:22px;margin-top:0}.note{border-left:4px solid #c49652;padding-left:14px}img{width:100%;height:auto}.controls{display:flex;gap:9px;flex-wrap:wrap}input,select,button{font:inherit;border:1px solid #bdcdc5;border-radius:6px;padding:8px;background:white;color:#163135}button{cursor:pointer}input{flex:1;min-width:160px}.wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:650px}td,th{padding:11px;border-bottom:1px solid #e1e9e4;text-align:left;font-size:13px}th{color:#52686b}td:first-child{max-width:600px}td button{border:0;padding:0;text-align:left;background:transparent}.row{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap}a{color:#126c62}.links{display:flex;gap:20px;flex-wrap:wrap}dialog{width:94vw;max-width:820px;max-height:90vh;overflow:auto;border:1px solid #a6c2b3;border-radius:12px;padding:24px}dialog::backdrop{background:#0c242ba1}.axes{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.axes div{background:#eff4ef;padding:12px}.axes b{display:block;font-size:24px}details{margin:16px 0}footer{font-size:12px;color:#52686b;margin-bottom:25px}@media(max-width:700px){.cards,.axes{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}main{padding:14px}section,.card{padding:14px}.number{font-size:24px}}</style>
<header><small style="color:#9dd7bc">NEWS2NEURON / RISK EVALUATION v5</small><h1>큰 오차를 줄이고,<br>남은 오차도 함께 기록합니다.</h1><p>기존 평가 자료는 개발용으로 전환했습니다. 새 기사의 예측을 먼저 고정한 뒤 Codex가 판단해 비교했습니다. 같은 사건의 후속 보도는 주 지표에서 분리하고 전체 결과도 보존했습니다.</p><p>0–100은 기사 발행 당시 서술의 잔존 위험 지수이며, 실제 발생 확률·독자의 스트레스·인간 정답 정확도가 아닙니다.</p></header><main>
<div class="cards"><div class="card"><small>평가한 실제 기사</small><div class="number" id="total"></div></div><div class="card"><small>직접 AI 판정 / 개발 자료</small><div class="number" id="direct"></div></div><div class="card"><small>같은 새 표본의 평균 오차</small><div class="number" id="mae"></div></div><div class="card"><small>10점 이내 AI 일치율</small><div class="number" id="agreement"></div></div></div>
<section><h2>동일한 새 기사에서 비교했습니다.</h2><p id="sample"></p><img src="figures/fresh_accuracy_comparison.png" alt="동일한 새 표본의 평균 오차와 10점 이내 AI 일치율 비교"><p class="note">평균 절대오차는 감소했지만 10점 이내 일치율은 개선되지 않았습니다. 작은 동일 AI 표본의 결과이며 독립 정답에 대한 성능 보장은 아닙니다. 임계값 근처의 작은 차이와 큰 오차의 감소를 함께 봐야 합니다.</p><div class="wrap"><table><thead><tr><th>모델</th><th>표본</th><th>기사 수</th><th>평균 절대오차 /100</th><th>10점 이내 AI 일치율</th></tr></thead><tbody id="comparison"></tbody></table></div><details><summary>검증 방법과 표본의 한계</summary><p>이전 검증 자료를 새 테스트로 재사용하지 않았습니다. v4 후보는 일반 기사의 오탐이 늘어 기본 모델로 채택하지 않았고, 그 자료를 개발용으로 전환했습니다. v5는 사건군을 나눈 교차검증에서 모델을 선택하고 새 평가 전 가중치·예측·입력을 고정했습니다.</p><p>새 32건 중 같은 사건·정책의 후속 보도 5건은 모델 점수를 보기 전에 따로 표시했습니다. 주 비교는 나머지 27건이며 무작위 16건과 점검용 11건입니다. 자동·수동 분리가 모든 의미적 관계를 발견했다는 보장은 없습니다. 모든 32건의 민감도 결과도 JSON에 제공합니다.</p><p id="interval"></p></details></section>
<section><div class="row"><h2>기사별 위험 지수</h2><b id="count"></b></div><p class="muted">직접 AI 판정과 모델의 일반화 예측을 구분합니다. 제목을 누르면 근거와 보조 축을 볼 수 있습니다.</p><div class="controls"><input id="search" type="search" placeholder="제목·판정 근거 검색" aria-label="검색"><select id="source" aria-label="매체"><option value="">모든 매체</option></select><select id="kind" aria-label="판정 유형"><option value="">모든 판정</option><option value="direct">직접 AI 판정</option><option value="model">모델 예측</option><option value="eligible">연구용 포함</option></select><select id="sort" aria-label="정렬"><option value="risk">위험 높은 순</option><option value="recent">최근 기사 순</option></select></div><div class="wrap"><table><thead><tr><th>기사 / 매체</th><th>위험 지수</th><th>N / T / A</th><th>판정</th></tr></thead><tbody id="articles"></tbody></table></div><div class="row" style="margin-top:15px"><button id="prev">이전</button><span id="page"></span><button id="next">다음</button></div></section>
<section><h2>데이터와 검증 기록</h2><div class="links"><a href="news_risk_scores.csv">전체 점수 CSV</a><a href="news_risk_scores.parquet">전체 점수 Parquet</a><a href="decision_audit.csv">직접 판단 원장</a><a href="fresh_audit_metrics.json">새 평가 결과</a><a href="audit_errors.csv">기사별 오차</a><a href="../../../docs/risk-accuracy-v5.md">방법·결과·한계</a><a href="../20261109_v3/report.html">이전 보고서</a></div></section><footer>8개 매체 · 2026-08-12~2026-11-09 한국어 뉴스. 독립 사람 평가 없이 현재 Codex가 기준 판정했습니다. 모델은 입력의 모든 본문 의미를 사용하지만 전체 기사를 하나씩 직접 정독한 판정으로 표시하지 않습니다.</footer></main>
<dialog id="detail"><div class="row"><b>ARTICLE ASSESSMENT</b><button id="close">닫기</button></div><h2 id="title"></h2><small id="meta"></small><p id="excerpt"></p><div class="axes" id="axes"></div><p id="rationale"></p><p class="note" id="method"></p><p id="state"></p><a id="original" target="_blank" rel="noopener noreferrer">기사 원문 ↗</a><details><summary>평가 본문 해시</summary><small id="hash" style="overflow-wrap:anywhere"></small></details></dialog>
<script type="application/json" id="payload">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('payload').textContent),$=id=>document.getElementById(id);let page=0,selected=[];const result=(m,c)=>D.metrics.results.find(r=>r.model===m&&r.cohort===c);const old=result('v3','novel_all'),now=result('v5','novel_all');$('total').textContent=D.summary.articles.toLocaleString();$('direct').textContent=D.summary.direct_AI_judgments+' / '+D.summary.development_articles;$('mae').textContent=old.MAE.toFixed(2)+' → '+now.MAE.toFixed(2);$('agreement').textContent=(100*old.within10_AI_agreement).toFixed(1)+' → '+(100*now.within10_AI_agreement).toFixed(1)+'%';$('sample').textContent='새 32건 중 관련 후속 보도 5건을 분리한 '+D.metrics.primary_articles+'건의 비교입니다. 각 모델의 순수 예측을 동일한 AI 기준과 비교했습니다.';$('interval').textContent='평균 오차 감소의 짝지은 재표집 95% 백분위 범위: '+D.metrics.paired_bootstrap_95_percentile.map(x=>x.toFixed(2)).join(' ~ ')+'점. 0을 포함하므로 미래 뉴스 전반에서의 우월성이 통계적으로 확인됐다고 주장하지 않습니다.';
for(const r of D.metrics.results.filter(r=>r.cohort.startsWith('novel_'))){const tr=document.createElement('tr');for(const v of [r.model,{novel_all:'주 비교',novel_random:'무작위',novel_stress:'어려운 기사'}[r.cohort],r.articles,r.MAE.toFixed(2),(r.within10_AI_agreement*100).toFixed(1)+'%']){const td=document.createElement('td');td.textContent=v;tr.append(td)}$('comparison').append(tr)}
[...new Set(D.articles.map(a=>a.source))].sort().forEach(s=>{const o=document.createElement('option');o.value=s;o.textContent=s;$('source').append(o)});
function open(a){$('title').textContent=a.title;$('meta').textContent=a.source+' · '+a.published_date+' · '+(a.session_reviewed?'직접 AI 판정':'모델 예측');$('excerpt').textContent=a.summary;$('axes').replaceChildren();for(const [k,label] of [['danger_score','위험 지수'],['N','부정성 N'],['T','잔존 위협 T'],['A','정서 강도 A'],['S','심각도 S'],['L','발생 근거 L'],['I','임박성 I'],['X','범위 X']]){const div=document.createElement('div');div.textContent=label;const b=document.createElement('b');b.textContent=(k==='danger_score'?a[k]:a[k]*4).toFixed(1)+(k==='danger_score'?' /100':' /4');div.append(b);$('axes').append(div)}$('rationale').textContent=a.rationale;$('method').textContent=a.session_reviewed?'직접 판단한 S/L/I/X의 기준식으로 지수를 산출했습니다.':'모델은 AI 기준 지수를 직접 학습합니다. 보조 축의 평균을 곱한 값('+a.component_index.toFixed(1)+')과 지수 예측은 다를 수 있습니다. 둘 다 실제 발생 확률은 아닙니다.';$('state').textContent='상태: '+a.decision_state+' · '+(a.assessment_research_eligible?'연구용 포함':'연구용 제외')+' · 발행 당시 서술 기준';$('hash').textContent=a.assessment_body_sha256;$('original').href=a.url.startsWith('https://')?a.url:'#';$('detail').showModal()}
function render(){const q=$('search').value.toLowerCase(),s=$('source').value,k=$('kind').value;selected=D.articles.filter(a=>(!s||a.source===s)&&(!q||(a.title+' '+a.rationale).toLowerCase().includes(q))&&(!k||(k==='direct'&&a.session_reviewed)||(k==='model'&&!a.session_reviewed)||(k==='eligible'&&a.assessment_research_eligible)));selected.sort((a,b)=>$('sort').value==='recent'?b.published_date.localeCompare(a.published_date):b.danger_score-a.danger_score);page=Math.min(page,Math.max(0,Math.ceil(selected.length/40)-1));$('count').textContent=selected.length.toLocaleString()+'건';$('articles').replaceChildren();for(const a of selected.slice(page*40,(page+1)*40)){const tr=document.createElement('tr'),td=document.createElement('td'),bt=document.createElement('button');bt.textContent=a.title;bt.onclick=()=>open(a);td.append(bt,document.createElement('br'));const sm=document.createElement('small');sm.textContent=a.source+' · '+a.published_date.slice(0,10);td.append(sm);tr.append(td);for(const v of [a.danger_score.toFixed(1),[a.N,a.T,a.A].map(x=>(x*4).toFixed(1)).join(' / '),a.session_reviewed?'직접 AI':'모델']){const t=document.createElement('td');t.textContent=v;tr.append(t)}$('articles').append(tr)}$('page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(selected.length/40));$('prev').disabled=page===0;$('next').disabled=(page+1)*40>=selected.length}
['search','source','kind','sort'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()}));$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('close').onclick=()=>$('detail').close();render();
</script></html>'''
    (out/'report.html').write_text(html.replace('PAYLOAD',payload),encoding='utf-8')
    return out/'report.html'
